37	        expression = "java(identityKey(owner))")
38	    @Mapping(target = "checkDigit",
39	        expression = "java(checkDigit(owner))")
40	    @Mapping(target = "ageBand",
41	        expression = "java(ageBand(owner))")
42	    @Mapping(target = "sharesHousehold", ignore = true)
43	    OwnerDto toOwnerDto(Owner owner);
44	
45	    /**
46	     * Derive the owner's age band from the supplied birthDate, evaluated against the owner's
47	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18 to 64 inclusive, and 'SENIOR' when
48	     * 65 or older. Returns null when no birthDate was supplied (or no registrationDate is available)
49	     * so owners without a birth date serialize cleanly.
50	     */
51	    default String ageBand(Owner owner) {
52	        java.time.LocalDate birthDate = owner.getBirthDate();
53	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
54	        if (birthDate == null || registrationDate == null) {
55	            return null;
56	        }
57	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
58	        if (age < 18) {
59	            return "MINOR";
60	        }
61	        if (age < 65) {
62	            return "ADULT";
63	        }
64	        return "SENIOR";
65	    }
66	
67	    /**
68	     * The E.164 country calling codes whose split from the national number is recognised when
69	     * formatting {@code telephoneDisplay} (matching the codes validated on create). The longest
70	     * matching code wins so a shorter code that is a prefix of another cannot mask it.
71	     */
72	    java.util.Set<String> KNOWN_COUNTRY_CODES = java.util.Set.of("1", "61");
73	
74	    /**
75	     * Format the stored E.164 telephone for humans: the '+' and country calling code, a space, then
76	     * the national digits grouped in threes (e.g. '+61412345678' -&gt; '+61 412 345 678'). The
77	     * country code is split off using the recognised calling codes; when none matches, a single-digit
78	     * code is assumed so the value is still rendered as '+&lt;code&gt; &lt;grouped national&gt;'.
79	     * Returns the stored value unchanged when it is null or not in E.164 form.
80	     */
81	    default String telephoneDisplay(Owner owner) {
82	        String telephone = owner.getTelephone();
83	        if (telephone == null || !telephone.startsWith("+")) {
84	            return telephone;
85	        }
86	        String digits = telephone.substring(1);
87	        if (!digits.matches("\\d+")) {
88	            return telephone;
89	        }
90	        String countryCode = digits.substring(0, 1);
91	        String national = digits.substring(1);
92	        for (int codeLength = Math.min(3, digits.length() - 1); codeLength >= 1; codeLength--) {
93	            String candidate = digits.substring(0, codeLength);
94	            if (KNOWN_COUNTRY_CODES.contains(candidate)) {
95	                countryCode = candidate;
96	                national = digits.substring(codeLength);
97	                break;
98	            }
99	        }
100	        StringBuilder grouped = new StringBuilder();
101	        for (int i = 0; i < national.length(); i++) {
102	            if (i > 0 && i % 3 == 0) {
103	                grouped.append(' ');
104	            }
105	            grouped.append(national.charAt(i));
106	        }
107	        return "+" + countryCode + " " + grouped;
108	    }
109	
110	    /**
111	     * Compute the owner's check digit: a single Luhn check digit (0-9) over the digits contained in
112	     * the customerCode. Returns null when no customerCode has been assigned so owners without a code
113	     * serialize cleanly.
114	     */
115	    default Integer checkDigit(Owner owner) {
116	        String customerCode = owner.getCustomerCode();
117	        if (customerCode == null) {
118	            return null;
119	        }
120	        int sum = 0;
121	        boolean dbl = true;
122	        for (int i = customerCode.length() - 1; i >= 0; i--) {
123	            char c = customerCode.charAt(i);
124	            if (c < '0' || c > '9') {
125	                continue;
126	            }
127	            int d = c - '0';
128	            if (dbl) {
129	                d *= 2;
130	                if (d > 9) {
131	                    d -= 9;
132	                }
133	            }
134	            sum += d;
135	            dbl = !dbl;
136	        }
137	        return (10 - (sum % 10)) % 10;
138	    }
139	
140	    /**
141	     * Derive the owner's identity key, the single value into which all duplicate detection is
142	     * consolidated: {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two
143	     * owners are duplicates only when their whole identity keys are equal. A null email or
144	     * householdId contributes an empty segment.
145	     */
146	    default String identityKey(Owner owner) {
147	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
148	        String email = owner.getEmail() == null ? "" : owner.getEmail();
149	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
150	        return telephone + "|" + email + "|" + householdId;
151	    }
152	
153	    /**
154	     * Determine the owner's preferred contact channel: 'EMAIL' when an email address is present,
155	     * otherwise 'PHONE'.
156	     */
157	    default String contactPreference(Owner owner) {
158	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
159	        return hasEmail ? "EMAIL" : "PHONE";
160	    }
161	
162	    /**
163	     * Build the owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is
164	     * the last two digits of the registrationDate year. Returns null when either source field is
165	     * absent so owners without an assigned code or registration date serialize cleanly.
166	     */
167	    default String membershipNumber(Owner owner) {
168	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
169	            return null;
170	        }
171	        return String.format("%s-M%02d", owner.getCustomerCode(),
172	            owner.getRegistrationDate().getYear() % 100);
173	    }
174	
175	    /**
176	     * Determine the owner's numeric membership level. Starts at 1; add 1 when an email address is
177	     * present; add 1 when the owner has no namesakes (namesakeCount is 0). These pre-tenure factors
178	     * are capped at 3. Level 4 is a loyalty tier reserved for tenure of more than 365 days, measured
179	     * from the registrationDate to the current date; because a newly created owner has zero tenure,
180	     * a new owner never exceeds level 3.
181	     */
182	    default Integer membershipLevel(Owner owner) {
183	        int level = 1;
184	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
185	        if (hasEmail) {
186	            level++;
187	        }
188	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
189	        if (noNamesakes) {
190	            level++;
191	        }
192	        // The pre-tenure factors above are capped at 3. Level 4 is the tenure loyalty tier: it
193	        // requires tenure of more than 365 days measured from the registrationDate. A new owner is
194	        // registered on the current date, so its tenure is zero and it can never reach level 4.
195	        level = Math.min(level, 3);
196	        if (owner.getRegistrationDate() != null && java.time.temporal.ChronoUnit.DAYS.between(
197	                owner.getRegistrationDate(), java.time.LocalDate.now()) > 365) {
198	            level++;
199	        }
200	        return level;
201	    }
202	
203	    /**
204	     * The fixed city-to-region table used to derive an owner's locality when the postcode is absent
205	     * or falls in no known range.
206	     */
207	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
208	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
209	
210	    /**
211	     * Region -&gt; inclusive 4-digit postcode range {low, high}: NSW 2000-2099, VIC 3000-3099,
212	     * QLD 4000-4099.
213	     */
214	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
215	        "NSW", new int[] {2000, 2099},
216	        "VIC", new int[] {3000, 3099},
217	        "QLD", new int[] {4000, 4099});
218	
219	    /**
220	     * Derive the owner's locality (canonical region), preferring the postcode: look up the region by
221	     * postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only fall back to the
222	     * city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is
223	     * absent or in no known range. Returns 'UNKNOWN' when neither source resolves a region.
224	     */
225	    default String locality(Owner owner) {
226	        String postcode = owner.getPostcode();
227	        if (postcode != null && postcode.matches("\\d{4}")) {
228	            int value = Integer.parseInt(postcode);
229	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
230	                int[] range = entry.getValue();
231	                if (value >= range[0] && value <= range[1]) {
232	                    return entry.getKey();
233	                }
234	            }
235	        }
236	        String city = owner.getCity();
237	        if (city == null) {
238	            return "UNKNOWN";
239	        }
240	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
241	    }
242	
243	    Owner toOwner(OwnerDto ownerDto);
244	
245	    @Mapping(target = "id", ignore = true)
246	    @Mapping(target = "pets", ignore = true)
