252	
253	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
254	        OwnerPageDto ownerPageDto = new OwnerPageDto();
255	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
256	        ownerPageDto.setPage(ownerPage.getNumber());
257	        ownerPageDto.setSize(ownerPage.getSize());
258	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
259	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
260	        return ownerPageDto;
261	    }
